echo OK nox-editor-s1.js $(wc -c <nox-editor-s1.js)
cd /workspace/nox/web/site
cp -n editor.html editor.html.bak_s1_1
python3 - <<'P'
import re
s=open('editor.html',encoding='utf-8').read()
if 'nox-editor-s1.js' not in s:
    main=open('editor-s1.main.html',encoding='utf-8').read()
    s=re.sub(r'<main.*?</main>',lambda m:main,s,count=1,flags=re.S)
    s=s.replace('</head>','<link rel="stylesheet" href="/web/nox-editor-s1.css?v=1"></head>',1)
    s=s.replace('</body>','<script type="module" src="/web/nox-editor-s1.js?v=1"></script></body>',1)
    open('editor.html','w',encoding='utf-8').write(s)
P
sed -i 's#nox-editor-s1.css?v=[0-9]*#nox-editor-s1.css?v='$(date +%s)'#; s#nox-editor-s1.js?v=[0-9]*#nox-editor-s1.js?v='$(date +%s)'#' editor.html
grep -c nox-editor-s1 editor.html; grep -o 'data-page="[a-z]*"' editor.html | head -1
ls vendor/nox-x/monaco/min/vs/loader.js vendor/pdfjs/pdf.min.mjs
cat > qa/rework/editor.fixed <<'F'
editor.html (S1, 25.11): две вкладки. «Документы PDF» - раскладка Adobe Acrobat web: миниатюры слева, страница по центру, панель (страницы, масштаб, повернуть, удалить страницу, сохранить копию) на pdf.js (vendor/pdfjs) и pdf-lib (vendor/nox-x/pdflib), всё локально в браузере. «Код» - раскладка VS Code web: панель действий, проводник, вкладки файлов, Monaco (vendor/nox-x/monaco), терминал xterm (vendor/nox-x/xterm) только с безопасными командами NOX (help/status/events/files/date/clear), без shell; файлы в localStorage. nox-editor-s1.css/js, бэкап editor.html.bak_s1_1.
F
cd /tmp; /workspace/nox/venv/bin/python /workspace/nox/tools/s1_shot.py editor.html ed1 vp=pc 2>&1 | cut -c1-900
